import React from 'react';
import { type Types } from '@fiverr-private/theme';
import { Center } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import { Skeleton, SkeletonSquare } from '@fiverr-private/feedback';
import { I18n } from '@fiverr-private/i18n-react';
import { ChevronButton } from '@fiverr-private/button';
import { useTableContext } from '../Table/TableContext';

const TablePagination = ({
  dataTrackTag = 'table_pagination',
  dataTrackValue,
}: Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => {
  const { table, loading } = useTableContext();
  const { pageIndex, pageSize } = table.getState().pagination;
  const initialRender = !table.getRowModel().rows.length && loading;
  const currentPageRowCount = table?.getPaginationRowModel()?.rows.length;
  const startIndex = pageIndex * pageSize + 1;
  const endIndex = pageIndex * pageSize + currentPageRowCount;
  const totalRows = table.getRowCount();

  return (
    <Center dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} direction="row" gap="4">
      {initialRender ? (
        <Skeleton>
          <SkeletonSquare height="22px" width="180px" />
        </Skeleton>
      ) : (
        <>
          <ChevronButton
            ariaLabel="prev"
            size="xs"
            shape="circle"
            chevronDirection="left"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage() || loading}
            dataTrackTag="table_pagination_previous_button"
          />
          <Text size="b_sm" whiteSpace="nowrap">
            <I18n k="table.pagination.page_count" params={{ startIndex, endIndex, totalRows }} />
          </Text>
          <ChevronButton
            aria-label="next"
            size="xs"
            shape="circle"
            chevronDirection="right"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage() || loading}
            dataTrackTag="table_pagination_next_button"
          />
        </>
      )}
    </Center>
  );
};

TablePagination.displayName = 'TablePagination';
export default TablePagination;
