import React from 'react';
import { Box } from '@fiverr-private/theme';
import { useTableContext } from '../Table/TableContext';

import type { TableBodyProps } from './types';
import TableBodyLoading from './TableBodyLoading';

const TableBody = ({ children, height, position, initialRowCount = 0 }: TableBodyProps) => {
  const { table, loading } = useTableContext();
  const rowCount = table.getRowModel().rows.length;

  if (rowCount) {
    return (
      <Box as="tbody" height={height} position={position}>
        {children}
      </Box>
    );
  }

  if (loading) {
    return <TableBodyLoading initialRowCount={initialRowCount} height={height} position={position} />;
  }

  return null;
};

TableBody.displayName = 'TableBody';
export default TableBody;
