import React from 'react';
import { Box, type Types } from '@fiverr-private/theme';

interface TableHeadProps {
  children: Types.Box['children'];
  isSticky?: boolean;
}

const TableHead = ({ children, isSticky }: TableHeadProps) => (
  <Box as="thead" {...(isSticky && { position: 'sticky', top: 0, zIndex: '1' })}>
    {children}
  </Box>
);

TableHead.displayName = 'TableHead';
export default TableHead;
