import { useReactTable, getCoreRowModel, flexRender } from '@tanstack/react-table';
import React, { useMemo, useState } from 'react';
import { Button } from '@fiverr-private/button';
import { TrashBinIcon } from '@fiverr-private/visuals';
import Table from '../../../Table';
import TableActionsPanel from '../../../TableActionsPanel';
import TableActionsPanelActions from '../../../TableActionsPanel/TableActionsPanelActions';
import TableBody from '../../../TableBody';
import TableContainer from '../../../TableContainer';
import TableContainerHeader from '../../../TableContainerHeader';
import TableData from '../../../TableData';
import TableHead from '../../../TableHead';
import TableHeader from '../../../TableHeader';
import TableRow from '../../../TableRow';
import { columnsMulti } from '../../helpers';
import { generateMockData } from '../../utils';

const MuliSelectStory = () => {
  const data = useMemo(() => generateMockData(8), []);
  const [rowSelection, setRowSelection] = useState({});
  const table = useReactTable({
    data,
    columns: columnsMulti,
    getCoreRowModel: getCoreRowModel(),
    onRowSelectionChange: setRowSelection,
    state: {
      rowSelection,
    },
    initialState: {
      columnPinning: {
        left: ['select'],
      },
    },
  });

  return (
    <TableContainer table={table}>
      <TableContainerHeader>
        <TableActionsPanel>
          <TableActionsPanelActions>
            <Button alignSelf="flexEnd" aria-label="remove" variant="ghost" colorScheme="white" size="sm">
              <TrashBinIcon color="white" />
              Delete
            </Button>
          </TableActionsPanelActions>
        </TableActionsPanel>
      </TableContainerHeader>
      <Table>
        <TableHead>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHeader
                  paddingX={header.column.id === 'select' ? '3' : undefined}
                  justifyContent={header.column.id === 'visits' ? 'flexEnd' : undefined}
                  column={header.column}
                  key={header.id}
                >
                  {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                </TableHeader>
              ))}
            </TableRow>
          ))}
        </TableHead>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow row={row} key={row.id}>
              {row.getVisibleCells().map((cell) => (
                <TableData
                  textAlign={cell.column.id === 'visits' ? 'end' : undefined}
                  paddingX={cell.column.id === 'select' ? '3' : undefined}
                  cell={cell}
                  key={cell.id}
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableData>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default MuliSelectStory;
