import React from 'react';
import { Box } from '@fiverr-private/theme';
import { Skeleton, SkeletonSquare } from '@fiverr-private/feedback';
import { getPinnedStyles, getRowBackgroundColor } from '../utils';
import { useTableContext } from '../Table/TableContext';
import type { TableDataProps } from './types';

const TableData = ({ children, cell, style, pinnedType = 'default', paddingX = '4', ...rest }: TableDataProps) => {
  const { variant, loading, dynamicCellWidth, tableStyle, hoveredRowId } = useTableContext();
  const isRowHovered = hoveredRowId === cell?.row?.id;
  const backgroundColor = getRowBackgroundColor({ tableStyle, row: cell.row, isRowHovered });
  const isPinned = cell.column?.getIsPinned();
  const { style: pinnedStyle, ...restPinnedProps } = getPinnedStyles({
    backgroundColor,
    column: cell?.column,
    pinnedType,
    isRowHovered,
  });
  const getPaddingY = () => {
    const isPinned = cell.column?.getIsPinned();
    if (isPinned && pinnedType === 'noBorder') {
      return '0';
    }
    return variant === 'compact' ? '2' : '4';
  };

  return (
    <Box
      boxSizing="borderBox"
      as="td"
      paddingX={pinnedType === 'noBorder' ? '0' : paddingX}
      paddingY={getPaddingY()}
      alignContent="center"
      alignItems="center"
      height={variant === 'compact' ? '44px' : '88px'}
      style={{ ...style, ...pinnedStyle }}
      width={dynamicCellWidth ? undefined : cell?.column?.getSize()}
      borderColor="border"
      borderStyle="solid"
      borderTopWidth="sm"
      {...rest}
      {...restPinnedProps}
    >
      <Box
        webkitLineClamp={2}
        display="webkitBox"
        webkitBoxOrient="vertical"
        overflow="hidden"
        textOverflow="ellipsis"
        fontSize="b_sm"
        lineHeight="b_sm"
        color="grey_1200"
        height={isPinned && pinnedType === 'noBorder' ? '100%' : undefined}
      >
        {loading ? (
          <Skeleton width="100%">
            <SkeletonSquare height="20px" />
          </Skeleton>
        ) : (
          children
        )}
      </Box>
    </Box>
  );
};

TableData.displayName = 'TableData';
export default TableData;
