import React from 'react';
import { Container, Stack } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { containerHeaderClass } from './styles.ve.css';

const TableContainerHeader = ({ children }: { children: Types.FlexLayoutProps['children'] }) => {
  const tableTitle = findChildByType(children, 'TableTitle');
  const tableHeaderActions = findChildByType(children, 'TableHeaderActions');
  const restChildren = excludeChildrenByType(children, ['TableTitle', 'TableHeaderActions']);

  return (
    <Stack direction="column" gap="6" paddingBottom="10" className={containerHeaderClass}>
      {(tableTitle || tableHeaderActions) && (
        <Stack alignItems="center" justifyContent="spaceBetween" gap="2">
          {tableTitle}
          <Container alignSelf="flexStart">{tableHeaderActions}</Container>
        </Stack>
      )}
      {restChildren}
    </Stack>
  );
};

TableContainerHeader.displayName = 'TableContainerHeader';
export default TableContainerHeader;
