import {
  ColumnDef,
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  Table as TableType,
  flexRender,
  Row,
} from '@tanstack/react-table';
import { useVirtualizer, Virtualizer } from '@tanstack/react-virtual';
import React, { useMemo } from 'react';
import { faker } from '@faker-js/faker';
import { Person } from '../../utils';
import TableContainer from '../../../TableContainer';
import Table from '../../../Table';
import TableHead from '../../../TableHead';
import TableRow from '../../../TableRow';
import TableHeader from '../../../TableHeader';
import TableBody from '../../../TableBody';
import TableData from '../../../TableData';

const makeColumns = (num: number) =>
  [...Array(num)].map((_, i) => ({
    accessorKey: i.toString(),
    header: `Column ${i.toString()}`,
  }));

const makeData = (num: number, columns: ColumnDef<Person>[]) =>
  [...Array(num)].map(() => ({
    ...Object.fromEntries(columns.map((col: ColumnDef<Person>) => [col.accessorKey, faker.person.firstName()])),
  }));

const VirtualizedColumnsStory = () => {
  const columns = useMemo<ColumnDef<Person>[]>(() => makeColumns(100), []);
  const data = useMemo(() => makeData(100, columns), [columns]);

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    debugTable: true,
  });

  const visibleColumns = table.getVisibleLeafColumns();
  const tableContainerRef = React.useRef<HTMLTableElement>(null);
  const columnVirtualizer = useVirtualizer<HTMLDivElement, HTMLTableCellElement>({
    count: visibleColumns.length,
    estimateSize: (index) => visibleColumns[index].getSize(),
    getScrollElement: () => tableContainerRef.current,
    horizontal: true,
    overscan: 3,
  });

  const virtualColumns = columnVirtualizer.getVirtualItems();

  let virtualPaddingLeft;
  let virtualPaddingRight;

  if (virtualColumns?.length) {
    virtualPaddingLeft = virtualColumns[0]?.start ?? 0;
    virtualPaddingRight = columnVirtualizer.getTotalSize() - (virtualColumns[virtualColumns.length - 1]?.end ?? 0);
  }

  return (
    <TableContainer table={table}>
      <Table height="800px" ref={tableContainerRef}>
        <TableHead isSticky>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id} display="flex" width="100%">
              {virtualPaddingLeft ? <TableHeader width={virtualPaddingLeft} /> : null}
              {virtualColumns.map((virtualColumn) => {
                const header = headerGroup.headers[virtualColumn.index];
                return (
                  <TableHeader key={header.id} column={header.column} width={header.getSize()}>
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHeader>
                );
              })}
              {virtualPaddingRight ? <TableHeader width={virtualPaddingRight} /> : null}
            </TableRow>
          ))}
        </TableHead>
        <TableBodyWrapper
          columnVirtualizer={columnVirtualizer}
          table={table}
          tableContainerRef={tableContainerRef}
          virtualPaddingLeft={virtualPaddingLeft}
          virtualPaddingRight={virtualPaddingRight}
        />
      </Table>
    </TableContainer>
  );
};

interface TableBodyWrapperProps {
  columnVirtualizer: Virtualizer<HTMLDivElement, HTMLTableCellElement>;
  table: TableType<Person>;
  tableContainerRef: React.RefObject<HTMLDivElement>;
  virtualPaddingLeft: number | undefined;
  virtualPaddingRight: number | undefined;
}

const TableBodyWrapper = ({
  columnVirtualizer,
  table,
  tableContainerRef,
  virtualPaddingLeft,
  virtualPaddingRight,
}: TableBodyWrapperProps) => {
  const { rows } = table.getRowModel();
  const rowVirtualizer = useVirtualizer<HTMLDivElement, HTMLTableRowElement>({
    count: rows.length,
    estimateSize: () => 88,
    getScrollElement: () => tableContainerRef.current,
    measureElement:
      typeof window !== 'undefined' && navigator.userAgent.indexOf('Firefox') === -1
        ? (element) => element?.getBoundingClientRect().height
        : undefined,
    overscan: 5,
  });

  const virtualRows = rowVirtualizer.getVirtualItems();

  return (
    <TableBody height={`${rowVirtualizer.getTotalSize()}px`} position="relative">
      {virtualRows.map((virtualRow) => {
        const row = rows[virtualRow.index] as Row<Person>;
        const visibleCells = row.getVisibleCells();
        const virtualColumns = columnVirtualizer.getVirtualItems();

        return (
          <TableRow
            row={row}
            data-index={virtualRow.index}
            ref={(node) => rowVirtualizer.measureElement(node)}
            key={row.id}
            display="flex"
            position="absolute"
            transform={`translateY(${virtualRow.start}px)`}
            width="100%"
          >
            {virtualPaddingLeft ? <td style={{ display: 'flex', width: virtualPaddingLeft }} /> : null}
            {virtualColumns.map((vc) => {
              const cell = visibleCells[vc.index];
              return (
                <TableData cell={cell} display="flex" width={cell.column.getSize()} key={cell.id}>
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableData>
              );
            })}
            {virtualPaddingRight ? <td style={{ display: 'flex', width: virtualPaddingRight }} /> : null}
          </TableRow>
        );
      })}
    </TableBody>
  );
};

export default VirtualizedColumnsStory;
