import { Column, Row } from '@tanstack/react-table';
import { type Types } from '@fiverr-private/theme';
import { BLUR_2X, PINNED_BG_COLORS } from '../constants';
import { TableContainerProps } from './TableContainer/types';

interface GetRowBackgroundColor {
    tableStyle: TableContainerProps['tableStyle'];
    row?: Row<object>;
    isRowHovered?: boolean;
}

type RowBackgroundColor = Extract<Types.Color, 'grey_100' | 'white'>;
export const getRowBackgroundColor = ({
    tableStyle,
    row,
    isRowHovered = false,
}: GetRowBackgroundColor): RowBackgroundColor => {
    if (tableStyle === 'zebra' && row) {
        return row?.index % 2 === 0 ? 'white' : 'grey_100';
    }

    return isRowHovered ? 'grey_100' : 'white';
};

interface GetPinnedStyles {
    backgroundColor: RowBackgroundColor | 'grey_200';
    column?: Column<object>;
    pinnedType?: 'noBorder' | 'default';
    isRowHovered?: boolean;
    isHeader?: boolean;
}
export const getPinnedStyles = ({
    backgroundColor,
    column,
    pinnedType,
    isRowHovered,
    isHeader,
}: GetPinnedStyles): Types.BoxType => {
    const isPinned = column?.getIsPinned();
    if (!isPinned || !column) {
        return {
            backgroundColor,
        };
    }

    const isLastLeftPinnedColumn = isPinned === 'left' && column.getIsLastColumn('left');
    const isFirstRightPinnedColumn = isPinned === 'right' && column.getIsFirstColumn('right');
    const pinnedBackgroundColor = PINNED_BG_COLORS[backgroundColor];
    const isDefault = pinnedType === 'default';

    return {
        left: isPinned === 'left' ? `${column.getStart('left')}px` : undefined,
        right: isPinned === 'right' ? `${column.getAfter('right')}px` : undefined,
        position: isPinned ? 'sticky' : undefined,
        zIndex: '1',
        minWidth: isDefault ? column.getSize() : undefined,
        ...(isLastLeftPinnedColumn && {
            ...(isDefault && { borderRightWidth: 'sm' }),
            borderTopLeftRadius: isHeader ? 'lg' : undefined,
        }),
        ...(isFirstRightPinnedColumn && {
            ...(isDefault && { borderLeftWidth: 'sm' }),
            borderTopRightRadius: isHeader ? 'lg' : undefined,
        }),
        ...((isDefault || isRowHovered) && {
            background: pinnedBackgroundColor,
            style: {
                backdropFilter: BLUR_2X,
            },
        }),
    };
};
