import React from 'react';
import { type Types } from '@fiverr-private/theme';
import { Stack, Container, Center } from '@fiverr-private/layout_components';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { getRowBackgroundColor } from '../utils';
import { useTableContext } from '../Table/TableContext';
import { BLUR_2X, PINNED_BG_COLORS } from '../../constants';
import type { TableActionsCellProps } from './types';

const TableActionsCell = ({ children, cell, dataTrackTag = 'table_actions_cell', ...rest }: TableActionsCellProps) => {
  const { tableStyle, hoveredRowId } = useTableContext();
  const isRowHovered = hoveredRowId === cell?.row?.id;
  const tableActionsCellFloating = findChildByType(children, 'TableActionsCellFloating');
  const backgroundColor: Extract<Types.BackgroundColor, 'grey_100' | 'white'> = getRowBackgroundColor({
    tableStyle,
    row: cell.row,
    isRowHovered,
  });

  return (
    <Stack gap="0" direction="rowReverse" alignItems="center" height="100%" dataTrackTag={dataTrackTag} {...rest}>
      <Center
        paddingRight="3"
        paddingLeft="2"
        height="100%"
        background={!isRowHovered ? PINNED_BG_COLORS[backgroundColor] : undefined}
        style={!isRowHovered ? { backdropFilter: BLUR_2X } : undefined}
      >
        {excludeChildrenByType(children, 'TableActionsCellFloating')}
      </Center>
      {tableActionsCellFloating && (
        <Container visibility={isRowHovered ? 'visible' : 'hidden'} paddingLeft="3">
          {tableActionsCellFloating}
        </Container>
      )}
    </Stack>
  );
};

TableActionsCell.displayName = 'TableActionsCell';
export default TableActionsCell;
