import React, { Children } from 'react';
import { Box } from '@fiverr-private/theme';
import { findChildByType, excludeChildrenByType, renderChildren } from '@fiverr-private/ui_utils';
import { Collapsible } from '@fiverr-private/disclosure';
import { getRowBackgroundColor } from '../utils';
import { useTableContext } from '../Table/TableContext';
import type { TableRowCollapsibleProps } from './types';
import { getBorderLeftStyle } from './utils';

const TableRowCollapsible = ({
  children,
  expanded = false,
  onClick,
  row,
  dataTrackTag = 'table_row_collapsible',
  dataTrackValue,
}: TableRowCollapsibleProps) => {
  const { tableStyle, setHoveredRowId, hoveredRowId } = useTableContext();
  const isRowHovered = hoveredRowId === row?.id;
  const style = getBorderLeftStyle(expanded);
  const backgroundColor = getRowBackgroundColor({ tableStyle, row, isRowHovered });
  const tableRowCollapsibleContent = findChildByType(children, 'TableRowCollapsibleContent');
  const rowEventHandlers = {
    onMouseEnter: () => {
      if (row) {
        setHoveredRowId(row?.id);
      }
    },
    onMouseLeave: () => {
      setHoveredRowId(undefined);
    },
    onClick,
  };

  return (
    <>
      <Box
        as="tr"
        borderStyle="solid"
        borderColor="border"
        borderTopWidth="sm"
        backgroundColor={backgroundColor}
        cursor="pointer"
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        {...rowEventHandlers}
      >
        {Children.map(excludeChildrenByType(children, 'TableRowCollapsibleContent'), (child, index) =>
          index === 0
            ? renderChildren(child, {
                row,
                style,
                isRowHovered,
              })
            : child
        )}
      </Box>
      <Box as="tr" backgroundColor={backgroundColor} cursor="pointer" boxSizing="borderBox" {...rowEventHandlers}>
        <Box
          as="td"
          style={style}
          paddingY={expanded ? '3' : undefined}
          paddingX={expanded ? '4' : undefined}
          colSpan={row && row.getAllCells().length}
        >
          <Collapsible expanded={expanded}>
            <>{tableRowCollapsibleContent}</>
          </Collapsible>
        </Box>
      </Box>
    </>
  );
};

TableRowCollapsible.displayName = 'TableRowCollapsible';
export default TableRowCollapsible;
