import React, { forwardRef } from 'react';
import { Container } from '@fiverr-private/layout_components';
import { Box } from '@fiverr-private/theme';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { EmptyState, EmptyStateVisual, EmptyStateTitle, EmptyStateSubtitle } from '@fiverr-private/data_display';
import { SavedDeliveriesIllustration } from '@fiverr-private/visuals';
import { I18n } from '@fiverr-private/i18n-react';
import type { TableProps } from './types';
import { useTableContext } from './TableContext';

const Table = forwardRef<HTMLDivElement, TableProps>(
  ({ children, height, dataTrackTag = 'table', dataTrackValue }, ref) => {
    const { table, loading } = useTableContext();
    const emptyState = findChildByType(children, 'EmptyState');

    return (
      <Container
        ref={ref}
        borderColor="border"
        borderStyle="solid"
        borderWidth="sm"
        borderRadius="lg"
        overflow="auto"
        position="relative"
        height={height}
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
      >
        <Box width="100%" as="table" style={{ borderCollapse: 'separate' }} dataTrackTag={dataTrackTag}>
          {excludeChildrenByType(children, 'EmptyState')}
        </Box>
        {!table?.getRowModel()?.rows.length &&
          !loading &&
          (emptyState || (
            <EmptyState>
              <EmptyStateVisual>
                <SavedDeliveriesIllustration size="sm" />
              </EmptyStateVisual>
              <EmptyStateTitle>
                <I18n k="table.empty_state.no_results_found" />
              </EmptyStateTitle>
              <EmptyStateSubtitle>
                <I18n k="table.empty_state.try_adjusting_search_or_filters" />
              </EmptyStateSubtitle>
            </EmptyState>
          ))}
      </Container>
    );
  }
);

Table.displayName = 'Table';
export default Table;
