import { faker } from '@faker-js/faker';

export interface Person {
  id: number;
  firstName: string;
  lastName: string;
  age: number;
  visits: number;
  status: string;
  country: string;
}

export const countries = ['USA', 'Canada', 'Germany'];
export const statuses = ['In progress', 'Completed'];

export const generateMockData = (count: number): Person[] =>
  Array.from({ length: count }, (_, i) => ({
    id: i + 1,
    firstName: faker.person.firstName(),
    lastName: faker.person.lastName(),
    age: faker.number.int({ min: 1, max: 80 }),
    visits: faker.number.int({ min: 1000, max: 100000 }),
    country: faker.helpers.arrayElement(countries),
    status: faker.helpers.arrayElement(statuses),
  }));

export const fetchPaginatedData = (page, itemsPerPage): Promise<{ data: Person[]; rowCount: number }> => {
  const totalItems = generateMockData(15000);

  return new Promise((resolve) => {
    setTimeout(() => {
      const start = (page - 1) * itemsPerPage;
      const end = start + itemsPerPage;

      resolve({
        data: totalItems.slice(start, end),
        rowCount: totalItems.length,
      });
    }, 3000);
  });
};
