import { theme } from '@fiverr-private/theme';

export const getBorderLeftStyle = (expanded) => {
    const {
        animationDuration: { slow1, fast1 },
        animationTiming: { easeInOut },
        colors: { grey_1200 },
    } = theme;
    const boxShadowLeft = expanded ? `inset 4px 0 0 ${grey_1200}` : undefined;

    const transition = !expanded
        ? `padding ${slow1} ${easeInOut}, box-shadow ${slow1} ${easeInOut}`
        : `padding ${fast1} ${easeInOut}, box-shadow ${fast1} ${easeInOut}`;
    return {
        boxShadow: boxShadowLeft,
        transition,
    };
};
