import React from 'react';
import { Center, Stack } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { FilterIcon } from '@fiverr-private/visuals';
import { I18n } from '@fiverr-private/i18n-react';

const TableFilters = ({
  children,
  dataTrackTag = 'table_filters',
  dataTrackValue,
}: {
  children: Types.FlexLayoutProps['children'];
  dataTrackTag: Types.FlexLayoutProps['dataTrackTag'];
  dataTrackValue: Types.FlexLayoutProps['dataTrackValue'];
}) => {
  const tableSearchInput = findChildByType(children, 'TableSearchInput');
  const tableActiveFilters = findChildByType(children, 'TableActiveFilters');

  return (
    <Stack dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} direction="column" gap="4">
      <Stack justifyContent="spaceBetween" wrap="wrapReverse" width="100%">
        <Stack alignItems="center" gap="4" wrap="wrap">
          <Center direction="row" gap="2" whiteSpace="nowrap" color="grey_1200">
            <FilterIcon />
            <I18n k="table.filters.filter_by" />
          </Center>
          {excludeChildrenByType(children, ['TableSearchInput', 'TableActiveFilters'])}
        </Stack>
        {tableSearchInput}
      </Stack>
      {tableActiveFilters}
    </Stack>
  );
};

TableFilters.displayName = 'TableFilters';
export default TableFilters;
