import React, { ReactNode } from 'react';
import { Text } from '@fiverr-private/typography';
import { I18n } from '@fiverr-private/i18n-react';
import { useTableContext } from '../Table/TableContext';

const TableItemsCounter = ({
  itemCount,
  copies = { itemsCount: (count) => <I18n k="table.items_counter" params={{ count }} /> },
}: {
  itemCount?: number;
  copies?: { itemsCount: (count: number) => ReactNode };
}) => {
  const { table } = useTableContext();
  const currentPageRows = table.getPaginationRowModel().rows.length;

  return (
    <Text color="bodySecondary" paddingBottom="4">
      {copies.itemsCount(itemCount || currentPageRows)}
    </Text>
  );
};

TableItemsCounter.displayName = 'TableItemsCounter';
export default TableItemsCounter;
