import React, { useCallback } from 'react';
import { isEmpty } from 'lodash';
import { Stack } from '@fiverr-private/layout_components';
import { Button } from '@fiverr-private/button';
import { I18n } from '@fiverr-private/i18n-react';
import { TagCollection, Tag, TagCloseIcon } from '@fiverr-private/data_display';
import { useTableContext } from '../Table/TableContext';
import type { TableActiveFiltersProps } from './types';

const TableActiveFilters = ({
  children,
  showClearButton = false,
  activeFilters,
  onClickClear,
  dataTrackTag = 'table_active_filters',
  dataTrackValue,
}: TableActiveFiltersProps) => {
  const { table } = useTableContext();
  const capitalized = useCallback((word) => word[0].toLocaleUpperCase() + word.slice(1), []);
  const handleClick = (id) => table.setColumnFilters((prev) => prev.filter((filter) => filter.id !== id));

  return children || !isEmpty(activeFilters) ? (
    <Stack gap="2">
      {children || (
        <TagCollection dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} width="fit-content" size="sm">
          {activeFilters?.map(({ value, id }) => {
            const filterValue = Array.isArray(value) ? value.map((value) => capitalized(value)).join(', ') : value;
            return (
              <Tag
                dataTrackTag="active_filter"
                dataTrackValue={String(filterValue)}
                clickableArea="multi"
                ariaLabel={id}
                key={id}
                size="sm"
                onClick={() => handleClick(id)}
              >
                {`${capitalized(id)}: ${filterValue}`}
                <TagCloseIcon onClick={() => handleClick(id)} />
              </Tag>
            );
          })}
        </TagCollection>
      )}
      {showClearButton ? (
        <Button size="sm" variant="ghost" onClick={onClickClear}>
          <I18n k="table.active_filters.clear_all" />
        </Button>
      ) : null}
    </Stack>
  ) : null;
};

TableActiveFilters.displayName = 'TableActiveFilters';
TableActiveFilters.id = 'TableActiveFilters';
export default TableActiveFilters;
