import {
  ColumnFiltersState,
  PaginationState,
  useReactTable,
  getPaginationRowModel,
  getCoreRowModel,
  getFilteredRowModel,
  flexRender,
} from '@tanstack/react-table';
import { isEmpty } from 'lodash';
import React, { useMemo } from 'react';
import { IconButton, Button } from '@fiverr-private/button';
import { Dropdown, DropdownAnchor, DropdownContent, DropdownMenu, MenuItem } from '@fiverr-private/dropdown';
import { getContext } from '@fiverr-private/fiverr_context';
import { Select, OptionGroup, Option } from '@fiverr-private/forms';
import { useBreakpoint } from '@fiverr-private/hooks';
import { Stack } from '@fiverr-private/layout_components';
import { EllipsisIcon, DownloadIcon, ShareIcon, TrashBinIcon } from '@fiverr-private/visuals';
import { EmptyState, EmptyStateVisual, EmptyStateTitle, EmptyStateSubtitle } from '@fiverr-private/data_display';
import { Text } from '@fiverr-private/typography';
import Table from '../../../Table';
import TableActionsPanel from '../../../TableActionsPanel';
import TableActionsPanelActions from '../../../TableActionsPanel/TableActionsPanelActions';
import TableActiveFilters from '../../../TableActiveFilters';
import TableBody from '../../../TableBody';
import TableContainer from '../../../TableContainer';
import TableContainerFooter from '../../../TableContainerFooter';
import TableContainerHeader from '../../../TableContainerHeader';
import TableData from '../../../TableData';
import TableFilters from '../../../TableFilters';
import TableHead from '../../../TableHead';
import TableHeader from '../../../TableHeader';
import TableHeaderActions from '../../../TableHeaderActions';
import TableItemsCounter from '../../../TableItemsCounter';
import TablePagination from '../../../TablePagination';
import TableRow from '../../../TableRow';
import TableSearchInput from '../../../TableSearchInput';
import TableTitle from '../../../TableTitle';
import { columnsMulti, columnsActions } from '../../helpers';
import { generateMockData, statuses, countries } from '../../utils';

const FullCompositionStory = ({ footerText }: { footerText: string }) => {
  const data = useMemo(() => generateMockData(50), []);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([]);
  const activeFilters = useMemo(() => columnFilters.filter((f) => f.id !== 'firstName'), [columnFilters]);
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  });

  const table = useReactTable({
    data,
    columns: [...columnsMulti, columnsActions],
    getPaginationRowModel: getPaginationRowModel(),
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    onColumnFiltersChange: setColumnFilters,
    getFilteredRowModel: getFilteredRowModel(),
    state: {
      columnFilters,
      pagination,
    },
    initialState: {
      columnPinning: {
        left: ['select'],
        right: ['actions'],
      },
    },
  });
  const { isMobile } = getContext();
  const breakpoint = useBreakpoint();
  const isSmallScreen = isMobile || breakpoint === 'default';

  return (
    <TableContainer table={table} dataTestid="tableContainer">
      <TableContainerHeader>
        <TableTitle>
          Table Title - Full composition
          <Text>Table Subtitle</Text>
        </TableTitle>
        <TableHeaderActions>
          <Stack gap="1">
            <Dropdown>
              <DropdownAnchor embed>
                <IconButton size="sm" variant="ghost" aria-label="">
                  <EllipsisIcon />
                </IconButton>
              </DropdownAnchor>
              <DropdownContent appendToBody>
                <DropdownMenu>
                  <MenuItem>Option 1</MenuItem>
                  <MenuItem>Option 2</MenuItem>
                  <MenuItem>Option 3</MenuItem>
                  {isSmallScreen && (
                    <>
                      <MenuItem>Share</MenuItem>
                      <MenuItem>Download</MenuItem>
                    </>
                  )}
                </DropdownMenu>
              </DropdownContent>
            </Dropdown>

            {!isSmallScreen && (
              <>
                <IconButton size="sm" aria-label="download" variant="ghost" intent="secondary">
                  <DownloadIcon />
                </IconButton>
                <IconButton size="sm" aria-label="share" variant="ghost" intent="secondary">
                  <ShareIcon />
                </IconButton>
              </>
            )}
          </Stack>
          <Button intent="primary" size="sm" variant="outline">
            Buy from
          </Button>
        </TableHeaderActions>
        <TableFilters>
          <Select
            placeholder="Status"
            value={{ status: table.getColumn('status')?.getFilterValue() as string[] }}
            onChange={({ status }) => {
              table.getColumn('status')?.setFilterValue(isEmpty(status) ? undefined : status);
            }}
          >
            <OptionGroup isMulti name="status">
              {statuses.map((status) => (
                <Option key={status} value={status}>
                  {status}
                </Option>
              ))}
            </OptionGroup>
          </Select>
          <Select
            placeholder="Country"
            value={{ country: table.getColumn('country')?.getFilterValue() as string[] }}
            onChange={({ country }) => {
              table.getColumn('country')?.setFilterValue(isEmpty(country) ? undefined : country);
            }}
          >
            <OptionGroup isMulti name="country">
              {countries.map((country) => (
                <Option key={country} value={country}>
                  {country}
                </Option>
              ))}
            </OptionGroup>
          </Select>
          <TableSearchInput
            value={table.getColumn('firstName')?.getFilterValue() as string}
            onChange={(e) => {
              table.getColumn('firstName')?.setFilterValue(e.target.value);
            }}
          />
          <TableActiveFilters
            onClickClear={() => table.setColumnFilters((prev) => prev.filter((filter) => filter.id === 'firstName'))}
            showClearButton={Boolean(activeFilters.length)}
            activeFilters={activeFilters}
          />
        </TableFilters>
        <TableActionsPanel>
          <TableActionsPanelActions>
            <Button alignSelf="flexEnd" aria-label="remove" variant="ghost" colorScheme="white" size="sm">
              <TrashBinIcon color="white" />
              Delete
            </Button>
          </TableActionsPanelActions>
        </TableActionsPanel>
      </TableContainerHeader>
      <TableItemsCounter />
      <Table>
        <TableHead>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHeader
                  headerPinned={header.column.id === 'actions' ? false : undefined}
                  paddingX={header.column.id === 'select' ? '3' : undefined}
                  justifyContent={header.column.id === 'visits' ? 'flexEnd' : undefined}
                  column={header.column}
                  key={header.id}
                >
                  {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                </TableHeader>
              ))}
            </TableRow>
          ))}
        </TableHead>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow row={row} key={row.id}>
              {row.getVisibleCells().map((cell) => (
                <TableData
                  pinnedType={cell.column.id === 'actions' ? 'noBorder' : undefined}
                  textAlign={cell.column.id === 'visits' ? 'end' : undefined}
                  paddingX={cell.column.id === 'select' ? '3' : undefined}
                  cell={cell}
                  key={cell.id}
                >
                  {flexRender(cell.column.columnDef.cell, {
                    ...cell.getContext(),
                  })}
                </TableData>
              ))}
            </TableRow>
          ))}
        </TableBody>
        <EmptyState gap="4">
          <EmptyStateVisual />
          <EmptyStateTitle />
          <EmptyStateSubtitle />
        </EmptyState>
      </Table>
      <TableContainerFooter justifyContent="spaceBetween">
        {' '}
        {footerText} <TablePagination />
      </TableContainerFooter>
    </TableContainer>
  );
};

export default FullCompositionStory;
