import React, { useState } from 'react';
import { Container } from '@fiverr-private/layout_components';
import { TableContextProvider } from '../Table/TableContext';
import type { TableContainerProps } from './types';

const TableContainer = ({
  children,
  variant = 'default',
  tableStyle = 'default',
  table,
  loading,
  dynamicCellWidth = true,
  dataTestid,
  dataTrackTag = 'table_container',
  dataTrackValue,
}: TableContainerProps) => {
  const [hoveredRowId, setHoveredRowId] = useState<string | undefined>(undefined);

  return (
    <TableContextProvider
      value={{ variant, tableStyle, table, loading, dynamicCellWidth, hoveredRowId, setHoveredRowId }}
    >
      <Container
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        overflow="hidden"
        padding="1"
        data-testid={dataTestid}
      >
        {children}
      </Container>
    </TableContextProvider>
  );
};

TableContainer.displayName = 'TableContainer';
export default TableContainer;
