import React from 'react';
import { I18n } from '@fiverr-private/i18n-react';
import { Stack } from '@fiverr-private/layout_components';
import { Text } from '@fiverr-private/typography';
import { excludeChildrenByType, findChildByType } from '@fiverr-private/ui_utils';
import { useTableContext } from '../Table/TableContext';
import type { TableActionsPanelProps } from './types';

const TableActionsPanel = ({
  children,
  copies = {
    selectedItems: (itemsSelected: number) => (
      <I18n k="table.actions_panel.items_selected" params={{ count: itemsSelected }} />
    ),
  },
}: TableActionsPanelProps) => {
  const { table } = useTableContext();
  const itemsSelected = Object.keys(table?.getState().rowSelection).length;
  const tableActionsPanelActions = findChildByType(children, 'TableActionsPanelActions');

  return itemsSelected ? (
    <Stack
      justifyContent="spaceBetween"
      alignItems="center"
      backgroundColor="grey_1200"
      borderRadius="lg"
      color="white"
      paddingY="2"
      paddingX="6"
      paddingRight="2"
      paddingLeft="6"
      minHeight="52px"
    >
      <Text color="inherit" fontWeight="bold">
        {copies.selectedItems(itemsSelected)}
      </Text>
      {excludeChildrenByType(children, 'TableActionsPanelActions')}
      {tableActionsPanelActions}
    </Stack>
  ) : null;
};

TableActionsPanel.displayName = 'TableActionsPanel';
TableActionsPanel.id = 'TableActionsPanel';
export default TableActionsPanel;
