import React from 'react';
import { Box } from '@fiverr-private/theme';
import { ArrowDownIcon, ArrowUpIcon } from '@fiverr-private/visuals';
import { useHover } from '@fiverr-private/hooks';
import { Center, Stack } from '@fiverr-private/layout_components';
import { getPinnedStyles } from '../utils';
import { useTableContext } from '../Table/TableContext';
import type { TableHeaderProps } from './types';

const TableHeader = ({
  children,
  column,
  headerPinned = true,
  isSortable,
  width,
  onClick,
  flex,
  justifyContent,
  paddingX = '4',
}: TableHeaderProps) => {
  const backgroundColor = 'grey_200';
  const { variant, dynamicCellWidth } = useTableContext();
  const { style = {}, ...restPinnedProps } = headerPinned
    ? getPinnedStyles({ backgroundColor, column, pinnedType: 'default', isHeader: true })
    : {};
  const { hovered, onMouseEnter, onMouseLeave } = useHover();
  const sortedState = column?.getIsSorted();

  return (
    <Box
      as="th"
      boxSizing="borderBox"
      style={{ verticalAlign: 'initial', alignContent: 'center', textAlign: 'initial', ...style }}
      paddingY={variant === 'compact' ? '2.5' : '4'}
      width={dynamicCellWidth ? width : column?.getSize()}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      cursor={isSortable ? 'pointer' : undefined}
      paddingX={paddingX}
      whiteSpace="nowrap"
      fontWeight="semibold"
      color="grey_1200"
      fontSize="b_sm"
      lineHeight="b_sm"
      borderColor="border"
      borderStyle="solid"
      backgroundColor={backgroundColor}
      flex={flex}
      onClick={onClick}
      {...restPinnedProps}
    >
      <Stack alignItems="center" justifyContent={justifyContent} gap="1">
        {children}
        <Stack position="relative" alignItems="center">
          {(hovered || sortedState) && isSortable && (
            <Center as="span" position="absolute">
              {sortedState === 'desc' ? <ArrowDownIcon /> : <ArrowUpIcon />}
            </Center>
          )}
        </Stack>
      </Stack>
    </Box>
  );
};

TableHeader.displayName = 'TableHeader';
export default TableHeader;
