import { useReactTable, getCoreRowModel, flexRender, Table as TableType, Row } from '@tanstack/react-table';
import React, { useEffect, useMemo, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import Table from '../../../Table';
import TableContainer from '../../../TableContainer';
import TableHead from '../../../TableHead';
import TableHeader from '../../../TableHeader';
import TableRow from '../../../TableRow';
import { generateMockData, Person } from '../../utils';
import TableBody from '../../../TableBody';
import TableData from '../../../TableData';
import { withColumSize } from '../../helpers';

interface TableBodyProps {
  table: TableType<Person>;
  tableContainerRef: React.RefObject<HTMLDivElement>;
}

const TableBodyWrapper = ({ table, tableContainerRef }: TableBodyProps) => {
  const { rows } = table.getRowModel();
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (tableContainerRef.current) {
      setReady(true);
    }
  }, [tableContainerRef]);

  const rowVirtualizer = useVirtualizer<HTMLDivElement, HTMLTableRowElement>({
    count: rows.length,
    estimateSize: () => 88,
    getScrollElement: () => (ready ? tableContainerRef.current : null),
    measureElement:
      typeof window !== 'undefined' && navigator.userAgent.indexOf('Firefox') === -1
        ? (element) => element?.getBoundingClientRect().height
        : undefined,
    overscan: 5,
  });

  return (
    <TableBody height={rowVirtualizer.getTotalSize()} position="relative">
      {rowVirtualizer.getVirtualItems().map((virtualRow) => {
        const row = rows[virtualRow.index] as Row<Person>;

        return (
          <TableRow
            row={row}
            dataIndex={virtualRow.index}
            ref={(node) => rowVirtualizer.measureElement(node)}
            key={row.id}
            display="flex"
            transform={`translateY(${virtualRow.start}px)`}
            position="absolute"
            width="100%"
          >
            {row.getVisibleCells().map((cell) => (
              <TableData
                justifyContent={cell.column.id === 'visits' ? 'flexEnd' : undefined}
                cell={cell}
                key={cell.id}
                flex={1}
                display="flex"
              >
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </TableData>
            ))}
          </TableRow>
        );
      })}
    </TableBody>
  );
};

export const VirtualizedRowsStory = () => {
  const tableContainerRef = React.useRef<HTMLDivElement>(null);
  const data = useMemo(() => generateMockData(5000), []);

  const table = useReactTable({
    data,
    columns: withColumSize,
    getCoreRowModel: getCoreRowModel(),
    debugTable: true,
  });

  return (
    <TableContainer table={table}>
      <Table ref={tableContainerRef} height="600px">
        <TableHead isSticky>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow display="flex" width="100%" key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHeader
                  justifyContent={header.column.id === 'visits' ? 'flexEnd' : undefined}
                  flex={1}
                  width={header.column.getSize()}
                  column={header.column}
                  key={header.id}
                >
                  {flexRender(header.column.columnDef.header, header.getContext())}
                </TableHeader>
              ))}
            </TableRow>
          ))}
        </TableHead>
        <TableBodyWrapper table={table} tableContainerRef={tableContainerRef} />
      </Table>
    </TableContainer>
  );
};
