import { createContext, useContext } from 'react';
import type { TableContainerProps } from '../../TableContainer/types';

interface TableContextType
  extends Pick<TableContainerProps, 'tableStyle' | 'table' | 'loading' | 'dynamicCellWidth' | 'variant'> {
  setHoveredRowId: React.Dispatch<React.SetStateAction<string | undefined>>;
  hoveredRowId: string | undefined;
}

const TableContext = createContext<TableContextType>({} as TableContextType);
export const TableContextProvider = TableContext.Provider;

export const useTableContext = () => {
  const context = useContext(TableContext);
  return context;
};
