import React from 'react';
import { SearchIcon } from '@fiverr-private/visuals';
import { InputGroup, InputPrefix, Input } from '@fiverr-private/forms';
import { translate } from '@fiverr-private/i18n-react';
import type { TableSearchInputProps } from './types';

const TableSearchInput = ({
  onChange,
  value = '',
  dataTrackTag = 'table_search_input',
  ...rest
}: TableSearchInputProps) => (
  <InputGroup
    dataTrackTag={dataTrackTag}
    onChange={onChange}
    value={value}
    width={{ default: '100%', sm: 'unset' }}
    {...rest}
  >
    <Input placeholder={translate<string>('table.search_input.search')} />
    <InputPrefix>
      <SearchIcon />
    </InputPrefix>
  </InputGroup>
);

TableSearchInput.displayName = 'TableSearchInput';
TableSearchInput.id = 'TableSearchInput';
export default TableSearchInput;
