import { type Cell } from '@tanstack/react-table';
import React from 'react';
import { Box } from '@fiverr-private/theme';
import TableData from '../../TableData';
import TableRow from '../../TableRow';
import type { TableBodyProps } from '../types';
import { useTableContext } from '../../Table/TableContext';

const TableBodyLoading = ({ height, position, initialRowCount = 0 }: Partial<TableBodyProps>) => {
  const { table } = useTableContext();
  const columns = table.getAllColumns();

  return (
    <Box as="tbody" height={height} position={position}>
      {Array.from({ length: initialRowCount }, (_, rowIndex) => (
        <TableRow key={`row-${rowIndex}`}>
          {columns.map((_, colIndex) => (
            <TableData key={`data-${rowIndex}-${colIndex}`} cell={{} as Cell<object, object>} />
          ))}
        </TableRow>
      ))}
    </Box>
  );
};

export default TableBodyLoading;
